#include <stdio.h>
int main() {
    int score = 85;
    if(score >= 90) {
        printf("Grade A\n");
    } else if(score >= 80) {
        printf("Grade B\n");
    } else {
        printf("Grade C or below\n");
    }

    printf("\nFor loop:\n");
    for(int i = 1; i <= 5; i++) {
        printf("%d\n", i);
    }

    printf("\nWhile loop:\n");
    int j = 1;
    while(j <= 3) {
        printf("%d\n", j);
        j++;
    }

    return 0;
}

