#include <stdio.h>
#include <string.h>
#include <ctype.h>
int main() {
    FILE *f = fopen("example.txt", "r");
    char word[100];
    int count = 0;
    while(fscanf(f, "%s", word) == 1) count++;
    fclose(f);
    printf("Words: %d\n", count);
    return 0;
}

#include <stdio.h>
int main() {
    FILE *src = fopen("example.txt", "r");
    FILE *dest = fopen("copy.txt", "w");
    char c;
    while((c = fgetc(src)) != EOF) fputc(c, dest);
    fclose(src);
    fclose(dest);
    printf("File copied successfully!\n");
    return 0;
}

